// Writes docs/OWNER_DECISIONS.md from the decision ledger.
// Run with: npm run ledger
import { writeFileSync, mkdirSync } from 'node:fs';
import { LEDGER } from '../src/data/ledger';
import { STATUS_HELP, STATUS_LABEL, Status } from '../src/data/types';

const ORDER: Status[] = ['owner-review', 'proposal', 'provisional', 'legacy', 'approved'];
const lines: string[] = [
  '# Decision ledger',
  '',
  'This file is generated by `npm run ledger` from `src/data/ledger.ts`. Edit the data file, not this one.',
  'The latest approved specification overrides the legacy site. Anything that fills a gap is labeled. Nothing here is world canon.',
  '',
];
for (const s of ORDER) {
  const list = LEDGER.filter((e) => e.status === s);
  lines.push(`## ${STATUS_LABEL[s]} (${list.length})`, '', STATUS_HELP[s], '');
  for (const e of list) {
    lines.push(`- **${e.area}.** ${e.decision} Source: ${e.source}.${e.note ? ` ${e.note}` : ''}`);
  }
  lines.push('');
}
mkdirSync(new URL('../docs/', import.meta.url), { recursive: true });
writeFileSync(new URL('../docs/OWNER_DECISIONS.md', import.meta.url), lines.join('\n'));
console.log(`Wrote docs/OWNER_DECISIONS.md with ${LEDGER.length} entries.`);
